class Solution {
public:
    vector<int> mostSimilar(int n, vector<vector<int>>& roads, vector<string>& names, vector<string>& targetPath) {
        int m = targetPath.size();
        vector<vector<int>> adj(n);
        for (const auto& r : roads) {
            adj[r[0]].push_back(r[1]);
            adj[r[1]].push_back(r[0]);
        }
        vector<vector<int>> dp(m, vector<int>(n, 1e9));
        vector<vector<int>> parent(m, vector<int>(n, -1));
        for (int u = 0; u < n; u++) {
            dp[0][u] = (names[u] == targetPath[0]) ? 0 : 1;
        }
        for (int t = 1; t < m; t++) {
            for (int u = 0; u < n; u++) {
                int cost = (names[u] == targetPath[t]) ? 0 : 1;
                for (int v : adj[u]) {
                    if (dp[t - 1][v] + cost < dp[t][u]) {
                        dp[t][u] = dp[t - 1][v] + cost;
                        parent[t][u] = v;
                    }
                }
            }
        }
        int bestEnd = 0;
        for (int u = 1; u < n; u++) {
            if (dp[m - 1][u] < dp[m - 1][bestEnd]) bestEnd = u;
        }
        vector<int> path;
        int curr = bestEnd;
        for (int t = m - 1; t >= 0; t--) {
            path.push_back(curr);
            curr = parent[t][curr];
        }
        reverse(path.begin(), path.end());
        return path;
    }
};

class Solution {
    public List<Integer> mostSimilar(int n, int[][] roads, String[] names, String[] targetPath) {
        int m = targetPath.length;
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] r : roads) {
            adj[r[0]].add(r[1]);
            adj[r[1]].add(r[0]);
        }
        int[][] dp = new int[m][n];
        int[][] parent = new int[m][n];
        for (int[] row : dp) Arrays.fill(row, 1_000_000_000);
        for (int u = 0; u < n; u++) {
            dp[0][u] = names[u].equals(targetPath[0]) ? 0 : 1;
        }
        for (int t = 1; t < m; t++) {
            for (int u = 0; u < n; u++) {
                int cost = names[u].equals(targetPath[t]) ? 0 : 1;
                for (int v : adj[u]) {
                    if (dp[t - 1][v] + cost < dp[t][u]) {
                        dp[t][u] = dp[t - 1][v] + cost;
                        parent[t][u] = v;
                    }
                }
            }
        }
        int bestEnd = 0;
        for (int u = 1; u < n; u++) {
            if (dp[m - 1][u] < dp[m - 1][bestEnd]) bestEnd = u;
        }
        List<Integer> path = new ArrayList<>();
        int curr = bestEnd;
        for (int t = m - 1; t >= 0; t--) {
            path.add(curr);
            curr = parent[t][curr];
        }
        Collections.reverse(path);
        return path;
    }
}

